:root {
  --cream: #f5ecd7;
  --ink: #2e1f0e;
  --rust: #a63d20;
  --gold: #c9922a;
  --border: #b59a6a;
  --label-bg: #e8d9b8;
  --footer-bg: #a63d20;
  --footer-text: #fdf4e3;
}

.ticket {
  background-color: var(--cream);
  border: 2px solid var(--border);
  border-radius: 6px;
  width: 360px;
  padding: 0;
  overflow: hidden;
  margin: 20px auto;
}

.ticket-header {
  background-color: var(--ink);
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
}

.theater-icon {
  font-size: 22px;
  line-height: 1;
}

.theater-name {
  color: var(--gold);
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin: 0;
}

.ticket-body {
  padding: 14px 16px 10px;
}

.show-title {
  color: var(--rust);
  font-size: 15px;
  font-weight: 700;
  margin: 0 0 10px;
  line-height: 1.3;
  border-bottom: 1px dashed var(--border);
  padding-bottom: 8px;
}

.ticket-details {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.ticket-details li {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.label {
  background-color: var(--label-bg);
  color: var(--ink);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border-radius: 3px;
  padding: 2px 6px;
}

.value {
  color: var(--ink);
  font-size: 13px;
  font-weight: 600;
}

.ticket-footer {
  background-color: var(--footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 16px;
  margin-top: 10px;
}

.admit {
  color: var(--footer-text);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.price {
  color: var(--gold);
  font-size: 16px;
  font-weight: 700;
}
